<script defer src="https://unpkg.com/alpinejs@3.14.1/dist/cdn.min.js"></script>
<style>
:root{
  --ink:#2A2520; --ink-soft:#4A4238; --muted:#7A7367;
  --paper:#E4E0D6; --card:#FBFAF6; --border:#D3CDBE; --border-strong:#BFB7A0;
  --navy:#3A2A18; --navy-soft:#4A3520; --navy-text:#F1EADB; --navy-text-dim:#B9AF97; --navy-line:rgba(255,244,222,.12);
  --accent:#9C7A3D; --accent-dark:#6E5527; --accent-bg:#EFE4CC; --accent-hover:#84652F;
  --success:#4C7A5C; --success-bg:#DEE9E0;
  --danger:#9C4632; --danger-bg:#EFDCD3;
  --radius:10px;
  --shadow:0 1px 2px rgba(30,22,14,.08), 0 10px 28px rgba(30,22,14,.12);
  --font-display:'Archivo','PingFang SC','Microsoft YaHei',sans-serif;
  --font-body:'IBM Plex Sans','PingFang SC','Microsoft YaHei',sans-serif;
  --font-mono:'IBM Plex Mono',ui-monospace,monospace;
}
*{box-sizing:border-box;}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--font-body);font-size:14px;-webkit-font-smoothing:antialiased;}
button{font-family:inherit;cursor:pointer;}
input,select,textarea{font-family:inherit;}
::selection{background:var(--accent-bg);}
button,.sub-row,.spec-row,.team-header,.chip,.scope-tab,.act-btn,.sub-act,.ptab,.icon-btn,.feed-item,.lang-pill,input,select,textarea{
  transition:background-color .12s ease,border-color .12s ease,color .12s ease,opacity .12s ease,box-shadow .12s ease;
}
button:focus-visible,.sub-row:focus-visible,a:focus-visible,input:focus-visible,[tabindex]:focus-visible{
  outline:2px solid var(--accent);outline-offset:1px;
}
a{color:inherit;}

.header-stack{position:sticky;top:0;z-index:80;}
[x-cloak]{display:none!important;}
.topbar{height:56px;background:var(--navy);color:var(--navy-text);
  display:flex;align-items:center;justify-content:space-between;padding:0 20px;border-bottom:1px solid var(--navy-line);}
.topbar-left{display:flex;align-items:center;gap:16px;min-width:0;}
.brand{display:flex;align-items:center;gap:10px;flex:none;text-decoration:none;color:inherit;}
.brand-mark{width:30px;height:30px;flex:none;}
.brand-text .name{font-family:var(--font-display);font-weight:600;font-size:15px;color:#fff;letter-spacing:.01em;}
.brand-text .sub{font-size:11px;color:var(--navy-text-dim);margin-top:1px;}
.topbar-divider{width:1px;height:22px;background:var(--navy-line);flex:none;}
.scope-switch{position:relative;flex:none;}
.scope-switch-btn{display:flex;align-items:center;gap:6px;background:var(--navy-line);border:none;color:var(--navy-text);font-size:12.5px;padding:6px 10px;border-radius:7px;font-weight:500;max-width:320px;}
.scope-switch-btn:hover{background:rgba(255,244,222,.18);}
.scope-switch-btn .sep{color:var(--navy-text-dim);}
.scope-switch-btn .chev{color:var(--navy-text-dim);font-size:10px;margin-left:2px;}
.scope-switch-btn .crumb-part{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:140px;}
.scope-menu{position:absolute;top:calc(100% + 6px);left:0;background:var(--card);border:1px solid var(--border);border-radius:var(--radius);box-shadow:var(--shadow);padding:8px;min-width:260px;max-height:70vh;overflow-y:auto;z-index:90;}
.scope-menu-group{margin-bottom:6px;}
.scope-menu-group:last-child{margin-bottom:0;}
.scope-menu-label{font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.04em;padding:4px 8px;}
.scope-menu-item{display:block;padding:6px 8px;border-radius:6px;font-size:13px;color:var(--ink-soft);text-decoration:none;}
.scope-menu-item:hover{background:var(--paper);}
.scope-menu-item.active{background:var(--accent);color:#fff;}
.topbar-right{display:flex;align-items:center;gap:16px;}
.user-chip{display:flex;align-items:center;gap:8px;padding-left:16px;border-left:1px solid var(--navy-line);}
.user-avatar{width:26px;height:26px;border-radius:50%;background:var(--navy-soft);color:var(--navy-text);display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:600;}
.user-chip .u-name{font-size:12.5px;color:var(--navy-text);}
.user-chip .u-role{font-size:10.5px;color:var(--navy-text-dim);}

.shell{display:flex;min-height:calc(100vh - 56px);}

.app-footer{padding:16px 20px;text-align:center;font-size:11.5px;color:var(--muted);border-top:1px solid var(--border);background:var(--paper);}
.app-footer a{color:var(--muted);text-decoration:none;}
.app-footer a:hover{color:var(--accent);}
.app-footer .footer-sep{margin:0 6px;}

/* 侧边栏：胡桃木饰面墙板质感（真实木纹照片 + 竖向板缝 + 顶部/底部暗角，替代纯色底） */
.sidebar{
  width:272px;flex:none;padding:14px 0 24px;overflow-y:auto;
  color:var(--navy-text);
  background-color:#4a3520;
  background-image:
    linear-gradient(90deg, rgba(20,14,7,.34) 0 1px, transparent 1px 76px),
    linear-gradient(180deg, rgba(255,244,222,.10), rgba(10,6,2,.42) 78%),
    url("data:image/jpeg;base64,");
  background-size:auto, 100% 100%, cover;
  background-position:left top, center, center 30%;
  background-repeat:repeat-x, no-repeat, no-repeat;
  box-shadow:inset -8px 0 18px rgba(0,0,0,.45), inset 0 0 0 1px rgba(0,0,0,.25);
}
.team-block{margin-bottom:2px;}
.team-header{display:flex;align-items:center;gap:6px;padding:9px 14px;user-select:none;}
.team-header:hover{background:rgba(0,0,0,.22);}
.team-header .t-name{font-family:var(--font-display);font-weight:700;font-size:16px;letter-spacing:.05em;text-transform:uppercase;color:#F8F2DE;text-shadow:0 1px 3px rgba(0,0,0,.6);text-decoration:none;flex:1;}
.team-header .t-count{font-family:var(--font-mono);font-size:13.5px;font-weight:600;color:#DDD1AC;text-shadow:0 1px 2px rgba(0,0,0,.5);}
.tree-icon{flex:none;}
.team-icon{color:#C79A4B;filter:drop-shadow(0 1px 2px rgba(0,0,0,.5));}
.spec-icon{color:#B9AF97;filter:drop-shadow(0 1px 2px rgba(0,0,0,.5));}
.sub-icon{color:#9A8F76;}
.spec-list{margin-left:23px;border-left:1px solid rgba(255,244,222,.14);}
.spec-row{display:flex;align-items:center;gap:6px;padding:7px 14px 7px 12px;}
.spec-row:hover{background:rgba(0,0,0,.22);}
.spec-row .s-name{font-size:16.5px;font-weight:600;color:#F8F2DE;text-shadow:0 1px 3px rgba(0,0,0,.55);text-decoration:none;flex:1;}
.spec-row .s-count{font-family:var(--font-mono);font-size:13.5px;font-weight:600;color:#DDD1AC;text-shadow:0 1px 2px rgba(0,0,0,.5);}
.spec-add{flex:none;width:18px;height:18px;border:1px solid rgba(255,244,222,.3);border-radius:5px;background:rgba(0,0,0,.25);color:#D8CFB8;display:flex;align-items:center;justify-content:center;}
.spec-add:hover{border-color:var(--accent-bg);color:var(--accent-bg);}
.tree-toggle{flex:none;width:22px;height:22px;border:none;background:none;color:#F8F2DE;display:flex;align-items:center;justify-content:center;padding:0;cursor:pointer;}
.tree-toggle-icon{display:inline-block;font-size:18px;line-height:1;text-shadow:0 1px 3px rgba(0,0,0,.7);transition:transform .12s ease;}
.tree-toggle-icon.open{transform:rotate(90deg);}
.sub-list{margin-left:19px;border-left:1px solid rgba(255,244,222,.1);}
.sub-row{display:flex;align-items:center;gap:8px;padding:6px 14px 6px 36px;cursor:pointer;border-left:3px solid transparent;font-size:16.5px;font-weight:600;color:#F3EBD3;text-shadow:0 1px 2px rgba(0,0,0,.5);text-decoration:none;}
.sub-row:hover{background:rgba(0,0,0,.22);}
.sub-row.selected{background:rgba(156,122,61,.4);color:#FFFAEC;text-shadow:0 1px 2px rgba(0,0,0,.45);border-left-color:var(--accent-bg);font-weight:700;box-shadow:inset 0 1px rgba(255,255,255,.1);}
.sub-row.selected .sub-icon{color:#FFFAEC;}
.sub-row .sub-name{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.badge-count{font-family:var(--font-mono);font-size:13px;font-weight:600;background:rgba(0,0,0,.4);color:#EFE6C9;padding:1px 6px;border-radius:999px;flex:none;}
.sub-row.selected .badge-count{background:rgba(255,255,255,.14);color:#FBF4E2;}

.main{flex:1;min-width:0;padding:28px 32px 60px;}
.main-inner{max-width:1000px;margin:0 auto;}
h1.page-title{font-family:var(--font-display);font-size:22px;font-weight:600;margin:0 0 4px;}
.page-sub{font-size:12.5px;color:var(--muted);margin:0 0 22px;}

.stat-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin-bottom:28px;}
.stat-card{background:var(--card);border:1px solid var(--border);border-radius:var(--radius);padding:14px 16px;}
.stat-card .label{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.04em;}
.stat-card .value{font-family:var(--font-display);font-size:24px;font-weight:600;margin-top:6px;}

h2.section-title{font-family:var(--font-display);font-size:15px;font-weight:600;margin:0 0 12px;}
.chip-row{display:flex;gap:6px;margin-bottom:14px;flex-wrap:wrap;}
.chip{border:1px solid var(--border);background:#fff;padding:5px 12px;border-radius:999px;font-size:12px;color:var(--ink-soft);text-decoration:none;}
.chip.active{background:var(--navy);border-color:var(--navy);color:#fff;}

.feed-item{display:flex;align-items:center;gap:14px;background:var(--card);border:1px solid var(--border);border-radius:var(--radius);padding:13px 16px;margin-bottom:9px;text-decoration:none;color:inherit;}
.feed-item:hover{box-shadow:var(--shadow);border-color:var(--border-strong);}
.feed-crumb{font-size:11px;color:var(--muted);margin-bottom:3px;}
.feed-crumb b{color:var(--ink-soft);font-weight:500;}
.feed-desc{font-size:13.5px;color:var(--ink);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.feed-meta{flex:none;text-align:right;}
.feed-ver{font-family:var(--font-mono);font-size:12.5px;font-weight:500;color:var(--ink);}
.feed-date{font-family:var(--font-mono);font-size:11px;color:var(--muted);margin-top:2px;}
.feed-langs{margin-top:4px;justify-content:flex-end;}

.sub-group{margin-bottom:18px;}
.sub-group-label{font-size:12px;color:var(--muted);margin-bottom:8px;font-weight:500;}
.sub-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:10px;}
.sub-tile{display:flex;align-items:center;justify-content:space-between;gap:8px;background:var(--card);border:1px solid var(--border);border-radius:var(--radius);padding:11px 14px;text-decoration:none;color:inherit;}
.sub-tile:hover{box-shadow:var(--shadow);border-color:var(--border-strong);}
.sub-tile-name{font-size:13px;color:var(--ink);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.sub-tile-count{flex:none;font-family:var(--font-mono);font-size:11px;color:var(--muted);background:var(--paper);border-radius:999px;padding:2px 8px;}

.crumb-nav{font-size:12.5px;color:var(--muted);margin-bottom:10px;}
.crumb-nav a{color:var(--muted);text-decoration:none;cursor:pointer;}
.crumb-nav a:hover{color:var(--accent);}
.crumb-nav b{color:var(--ink);font-weight:500;}

.detail-header{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;margin-bottom:20px;flex-wrap:wrap;}
.detail-header h1{margin:0;}
.tag-pill{display:inline-block;background:var(--paper);border:1px solid var(--border);color:var(--ink-soft);font-size:11.5px;padding:2px 9px;border-radius:999px;margin-left:8px;vertical-align:middle;}
.detail-actions{display:flex;gap:8px;align-items:center;}

.btn{border-radius:8px;padding:8px 14px;font-size:13px;font-weight:500;border:1px solid var(--border-strong);background:#fff;color:var(--ink);display:inline-flex;align-items:center;gap:6px;text-decoration:none;}
.btn:hover{border-color:var(--ink-soft);}
.btn-accent{background:var(--accent);border-color:var(--accent);color:#fff;}
.btn-accent:hover{background:var(--accent-hover);border-color:var(--accent-hover);}
.btn-ghost{border-color:transparent;background:transparent;}
.btn-ghost:hover{background:var(--paper);}
.btn-sm{padding:6px 10px;font-size:12px;}
.icon-btn{width:30px;height:30px;border-radius:7px;border:1px solid var(--border);background:#fff;display:flex;align-items:center;justify-content:center;color:var(--ink-soft);}
.icon-btn:hover{border-color:var(--ink-soft);color:var(--ink);}
.icon-btn.danger:hover{border-color:var(--danger);color:var(--danger);background:var(--danger-bg);}

.lang-badges{display:flex;gap:4px;flex-wrap:wrap;}
.lang-pill{font-family:var(--font-mono);font-size:10.5px;font-weight:600;padding:2px 7px;border-radius:5px;letter-spacing:.02em;border:1px solid transparent;display:inline-flex;align-items:center;gap:3px;line-height:1.5;text-decoration:none;}
.lang-pill.present{background:var(--success-bg);color:var(--success);}
.lang-pill.present.clickable:hover{background:#c9dbcd;}
.lang-pill.missing{background:transparent;color:var(--muted);border:1px dashed var(--border-strong);}
.lang-pill.missing.addable{cursor:pointer;color:var(--ink-soft);}
.lang-pill.missing.addable:hover{border-color:var(--accent);color:var(--accent-dark);}

.latest-card{position:relative;background:var(--card);border:1px solid var(--border);border-left:4px solid var(--accent);border-radius:var(--radius);padding:18px 20px;margin-bottom:26px;}
.latest-top{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:10px;}
.badge-latest{background:var(--accent-bg);color:var(--accent-dark);font-size:11px;font-weight:600;padding:3px 9px;border-radius:999px;letter-spacing:.02em;}
.ver-mono{font-family:var(--font-mono);font-weight:600;font-size:15px;}
.date-mono{font-family:var(--font-mono);font-size:12px;color:var(--muted);}
.spacer{flex:1;}
.latest-desc{font-size:14px;line-height:1.65;color:var(--ink);margin:0 0 14px;white-space:pre-wrap;}
.latest-row2{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px;flex-wrap:wrap;gap:10px;}
.file-chips{display:flex;gap:8px;flex-wrap:wrap;}
.file-chip{display:flex;align-items:center;gap:7px;border:1px solid var(--border);border-radius:8px;padding:6px 10px;font-size:12px;color:var(--ink-soft);background:var(--paper);text-decoration:none;}
.file-chip .fname{font-family:var(--font-mono);}
.latest-foot{display:flex;justify-content:space-between;align-items:center;font-size:11.5px;color:var(--muted);border-top:1px solid var(--border);padding-top:10px;}
.latest-actions{display:flex;gap:6px;}

table.revlog{width:100%;border-collapse:collapse;background:var(--card);border:1px solid var(--border);border-radius:var(--radius);overflow:hidden;}
table.revlog th{text-align:left;font-size:11px;text-transform:uppercase;letter-spacing:.03em;color:var(--muted);background:var(--paper);padding:9px 14px;font-weight:500;border-bottom:1px solid var(--border);}
table.revlog td{padding:11px 14px;border-bottom:1px solid var(--border);font-size:13px;vertical-align:middle;}
table.revlog tr:last-child td{border-bottom:none;}
table.revlog tr:hover td{background:var(--paper);}
td.mono{font-family:var(--font-mono);font-size:12.5px;}
td.desc-cell{color:var(--ink-soft);}
td.ops{white-space:nowrap;}
.ops-row{display:flex;gap:5px;}

.empty-state{text-align:center;padding:56px 20px;color:var(--muted);}
.empty-state p{font-size:13.5px;margin:0 0 16px;}

.overlay{position:fixed;inset:0;background:rgba(14,20,26,.46);display:flex;align-items:center;justify-content:center;z-index:200;padding:20px;}
.modal{background:var(--card);border-radius:14px;width:560px;max-width:100%;max-height:88vh;overflow-y:auto;box-shadow:var(--shadow);}
.modal.wide{width:720px;}
.modal-head{display:flex;align-items:center;justify-content:space-between;padding:18px 22px;border-bottom:1px solid var(--border);}
.modal-head h3{margin:0;font-family:var(--font-display);font-size:16px;font-weight:600;}
.modal-close{background:none;border:none;color:var(--muted);padding:4px;border-radius:6px;}
.modal-close:hover{background:var(--paper);color:var(--ink);}
.modal-body{padding:20px 22px;}
.modal-foot{display:flex;justify-content:flex-end;gap:8px;padding:16px 22px;border-top:1px solid var(--border);}
.field{margin-bottom:15px;}
.field label{display:block;font-size:12px;font-weight:500;color:var(--ink-soft);margin-bottom:5px;}
.field input[type=text],.field input[type=date],.field input[type=password],.field select,.field textarea{width:100%;padding:9px 11px;border:1px solid var(--border);border-radius:8px;font-size:13.5px;background:#fff;color:var(--ink);}
.field input:focus,.field select:focus,.field textarea:focus{outline:none;border-color:var(--accent);}
.field textarea{resize:vertical;min-height:70px;line-height:1.5;}
.field-row{display:flex;gap:12px;}
.field-row .field{flex:1;}
.field input[type=file]{width:100%;font-size:12px;padding:8px;border:1.5px dashed var(--border-strong);border-radius:9px;background:var(--paper);}
.hint{font-size:11px;color:var(--muted);margin-top:4px;}
.error-text{font-size:12px;color:var(--danger);margin-top:4px;}

.lang-section{border:1px solid var(--border);border-radius:10px;padding:14px 15px;margin-bottom:14px;}
.lang-section.zh{background:var(--paper);}
.lang-section-head{font-size:13px;font-weight:600;color:var(--ink);margin-bottom:12px;}

.toast{position:fixed;bottom:22px;right:22px;background:var(--ink);color:#fff;padding:11px 16px;border-radius:9px;font-size:13px;box-shadow:var(--shadow);z-index:300;}

.upload-queue{position:fixed;top:66px;right:18px;z-index:400;display:none;flex-direction:column;gap:8px;width:260px;}
.upload-item{background:var(--card);border:1px solid var(--border);border-radius:10px;padding:10px 12px;box-shadow:var(--shadow);}
.upload-item .ui-top{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:7px;}
.upload-item .ui-label{font-size:12.5px;color:var(--ink);font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.upload-item .ui-pct{font-size:11.5px;color:var(--muted);flex:none;font-variant-numeric:tabular-nums;}
.upload-item .ui-bar{height:5px;border-radius:3px;background:var(--paper);overflow:hidden;}
.upload-item .ui-bar-fill{height:100%;width:0%;background:var(--accent);border-radius:3px;transition:width .15s ease;}
.upload-item.ui-done .ui-bar-fill{background:var(--success);}
.upload-item.ui-done .ui-pct{color:var(--success);}
.upload-item.ui-processing .ui-bar-fill{animation:ui-pulse 1.3s ease-in-out infinite;}
.upload-item.ui-processing .ui-pct{color:var(--accent-dark);}
.upload-item.ui-error .ui-bar-fill{background:var(--danger);}
.upload-item.ui-error .ui-pct{color:var(--danger);}
.upload-item .ui-err-msg{font-size:11.5px;color:var(--danger);margin-top:6px;line-height:1.5;}
@keyframes ui-pulse{0%,100%{opacity:1;}50%{opacity:.35;}}
@media (prefers-reduced-motion: reduce){.upload-item.ui-processing .ui-bar-fill{animation:none;}}

.admin-shell{padding:28px 32px 70px;}
.admin-inner{max-width:880px;margin:0 auto;}
.admin-head-row{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:22px;gap:16px;flex-wrap:wrap;}
.admin-note{background:var(--accent-bg);color:var(--accent-dark);border-radius:9px;padding:11px 14px;font-size:12.5px;line-height:1.6;margin-bottom:20px;}
.team-card{background:var(--card);border:1px solid var(--border);border-radius:12px;margin-bottom:16px;overflow:hidden;}
.team-card-head{display:flex;align-items:center;gap:8px;padding:13px 16px;background:var(--paper);border-bottom:1px solid var(--border);}
.team-card-head .tc-name{font-family:var(--font-display);font-weight:600;font-size:14.5px;flex:1;}
.act-btn{width:24px;height:24px;border:none;background:none;color:var(--muted);border-radius:5px;display:flex;align-items:center;justify-content:center;flex:none;}
.act-btn:hover{background:#fff;color:var(--ink-soft);}
